contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint _val1, uint _val2) public payable {
        require(true);

        // Set up: initialize the contract first.
        c.Initialized();

        // Record MinSum before the deciding call.
        uint beforeMinSum = c.MinSum();

        // The deciding call: after initialization, SetMinSum must revert.
        bool reverted;
        try c.SetMinSum(_val1) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterMinSum = c.MinSum();

        // General rule: after Initialized, SetMinSum reverts and MinSum is unchanged.
        assert(reverted && afterMinSum == beforeMinSum);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint _val1, uint _val2) public payable {
        require(true);

        // Deciding call before initialization: SetMinSum must succeed.
        bool revertedBefore;
        try c.SetMinSum(_val1) {
            revertedBefore = false;
        } catch {
            revertedBefore = true;
        }
        uint minSumAfterFirst = c.MinSum();

        // Now initialize.
        c.Initialized();

        // Read MinSum before the second SetMinSum.
        uint beforeSecond = c.MinSum();

        // Deciding call after initialization: SetMinSum must revert.
        bool revertedAfter;
        try c.SetMinSum(_val2) {
            revertedAfter = false;
        } catch {
            revertedAfter = true;
        }
        uint afterSecond = c.MinSum();

        // General rule: pre-initialization succeeds and sets MinSum; post-initialization reverts and leaves MinSum unchanged.
        assert(!revertedBefore && minSumAfterFirst == _val1 && revertedAfter && afterSecond == beforeSecond);
    }

    receive() external payable {}
}

