contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint lockTime, uint amount) public payable {
        require(address(this).balance >= amount);

        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        bool beforeInitialized = c.intitalized();
        uint beforeMinSum = c.MinSum();

        bool reverted;
        try c.Put{value: amount}(lockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterMinSum = c.MinSum();

        assert(!reverted);
        assert(afterBalance == beforeBalance + amount);
        assert(afterMinSum == beforeMinSum);

        if (!beforeInitialized) {
            // sGuard's add_uint256 only asserts on overflow; with realistic
            // inputs it does not overflow, so the effective rule is that
            // Put always completes and credits exactly msg.value.
            assert(afterUnlock == beforeUnlock || afterUnlock > beforeUnlock);
        }
    }

    receive() external payable {}
}

