contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint _val) public {
        require(address(c).balance == 0, "fresh contract should have zero balance");

        uint beforeMinSum = c.MinSum();

        bool initReverted;
        try c.Initialized() {
            initReverted = false;
        } catch {
            initReverted = true;
        }

        uint afterInitMinSum = c.MinSum();

        bool setMinSumReverted;
        try c.SetMinSum(_val) {
            setMinSumReverted = false;
        } catch {
            setMinSumReverted = true;
        }

        uint afterSetMinSum = c.MinSum();

        assert(
            !initReverted &&
            afterInitMinSum == beforeMinSum &&
            setMinSumReverted &&
            afterSetMinSum == afterInitMinSum
        );
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint _val) public {
        // Parameter-only precondition: nothing about c.
        // Fresh c has MinSum == 0; capture it.
        uint before = c.MinSum();

        // Deciding call: Initialized() must never revert on a fresh contract.
        bool initializedReverted;
        try c.Initialized() {
            initializedReverted = false;
        } catch {
            initializedReverted = true;
        }

        // Capture MinSum after Initialized().
        uint after = c.MinSum();

        // General rule: Initialized() succeeds and does not change MinSum, regardless of _val.
        assert(!initializedReverted && after == before);
    }
}

